bounded_host_request.command:
set -eu
python3 - <<'PY'
import subprocess,sys,os
def sh(a):
 p=subprocess.run(a,capture_output=True,text=True,timeout=24)
 return p.returncode,p.stdout.strip(),p.stderr.strip()
rc,label,_=sh(['docker','inspect','deploy-gaybbs-1','--format','{{index .Config.Labels "com.docker.compose.project.config_files"}}'])
if rc:sys.exit(61)
paths=[x.strip() for x in label.split(',') if x.strip()]
if len(paths)!=2:sys.exit(62)
if not os.path.isfile(paths[0]):sys.exit(63)
if os.path.exists(paths[1]):sys.exit(64)
rc,_,err=sh(['docker','compose','-f',paths[0],'-p','deploy','config','-q'])
if rc:sys.exit(65)
rc,hashline,err=sh(['docker','compose','-f',paths[0],'-p','deploy','config','--hash','gaybbs'])
if rc:sys.exit(66)
rc,current,_=sh(['docker','inspect','deploy-gaybbs-1','--format','{{index .Config.Labels "com.docker.compose.config-hash"}}'])
if rc or not current:sys.exit(67)
if current in hashline:sys.exit(0)
sys.exit(68)
PY
